Decorators with arguments require an extra level of nesting. Here's an example:

```python
import functools

def repeat(times):
    """Decorator that repeats function execution"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

# Usage
@repeat(times=3)
def greet(name):
    print(f"Hello, {name}!")

greet("Alice")
# Output:
# Hello, Alice!
# Hello, Alice!
# Hello, Alice!
```

The structure is:
1. Outer function takes decorator arguments
2. Middle function takes the decorated function
3. Inner function is the actual wrapper

Another practical example with a retry decorator:

```python
import time
import functools

def retry(max_attempts=3, delay=1):
    """Retry failed function calls"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        raise
                    print(f"Attempt {attempt + 1} failed: {e}")
                    time.sleep(delay)
        return wrapper
    return decorator

@retry(max_attempts=3, delay=2)
def unstable_api_call():
    # Function that might fail
    import random
    if random.random() < 0.7:
        raise ConnectionError("API unavailable")
    return "Success!"
```
